/* @autogenerated */
import { Component, inject } from '@angular/core';
import { Template } from 'app/features/template/template/model/template.model';
import { TemplateRepository } from 'app/features/template/template/repository/template-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';

@Component({ selector: 'template-view-disable-selection-action', standalone: false, template: '' })
export class TemplateViewDisableSelectionActionComponent extends ConfirmSelectionAction<Template> {
  readonly name = 'disableSelection';
  protected readonly scope = 'template/template';
  protected readonly repository = inject(TemplateRepository);

  protected override appliesTo(items: Template[]) {
    return items.every((item) => item.enabled !== false);
  }

  protected runSelection(items: Template[]) {
    return this.repository.disableSelection({ uids: items.map((item) => item.uid) });
  }
}
